/**
 * Display names for uploaded files (Prompt 26), one rule everywhere.
 *
 * A file name is shown to people and may reach model context, so it is reduced
 * to a safe label: the last path segment only; Unicode normalised; control
 * characters, format characters (including the bidirectional overrides that
 * make `report‮fdp.png` display as `reportpng.pdf`) and characters
 * reserved by filesystems removed; leading dots dropped; bounded length.
 * Storage keys never use it — they are generated by the server.
 */
export function cleanFileName(
  raw: string | undefined | null,
  fallback: string,
  max = 120,
): string {
  const base =
    repairLatin1(raw ?? '')
      .split(/[\\/]/)
      .pop() ?? '';
  const cleaned = base
    .normalize('NFC')
    .replace(/[\p{Cc}\p{Cf}\p{Co}\p{Cn}]/gu, '')
    .replace(/[<>:"|?*;]/g, '')
    .replace(/^\.+/, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
  return cleaned || fallback;
}

/**
 * Multipart file names arrive decoded as Latin-1 (busboy/multer default), so a
 * UTF-8 name — Hindi, or a disguised bidi override — shows up as mojibake and
 * slips past character filters. Re-decode when the string is valid UTF-8 in
 * Latin-1 clothing; leave it alone otherwise.
 */
function repairLatin1(value: string): string {
  // Latin-1 ranges, not control characters, are what this tests for.
  // eslint-disable-next-line no-control-regex
  if (!/[\u0080-\u00ff]/.test(value) || /[^\u0000-\u00ff]/.test(value)) return value;
  const decoded = Buffer.from(value, 'latin1').toString('utf8');
  return decoded.includes('\uFFFD') ? value : decoded;
}
